const planByPath = new Map(networkPagePlans.map(plan => [plan.path,plan]));
export function networkPagePlan(path: string) { return planByPath.get(path); }
export function networkTopic(id: NetworkTopicId) { return networkTopics.find(topic => topic.id === id)!; }
export function networkTopicPath(id: NetworkTopicId) { const topic=networkTopic(id);return `/categories/${topic.category}#${topic.id}`; }
export function networkEditorialNote(value:string) {return value.replace(/;\s*(?:this|it) is(?: a)?\.\s*$/i,".");}
